export default function FileRow({ name, size, date }) {
  return (
    <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 p-4 border-b last:border-b-0">
      {/* File info */}
      <div>
        <p className="font-medium text-gray-800 break-all">
          {name}
        </p>
        <p className="text-xs text-gray-500">
          {size} • {date}
        </p>
      </div>

      {/* Actions */}
      <div className="flex gap-4 text-sm">
        <button className="text-blue-600 hover:underline">
          Download
        </button>
        <button className="text-red-500 hover:underline">
          Delete
        </button>
      </div>
    </div>
  );
}
